      pt: ["Comprimento: 500 km", "Bacia hidrográfica: 200.000 km²", "Caudal máximo: 600 m³/s (setembro)", "Rio fronteiriço com a Etiópia: 200 km", "Pesca: 5.000 t/ano", "Não navegável"],
      fr: ["Longueur : 500 km", "Bassin versant : 200 000 km²", "Débit maximal : 600 m³/s (septembre)", "Rivière frontalière avec l'Éthiopie : 200 km", "Pêche : 5 000 t/an", "Non navigable"],
